    /**
     * Method to retrieve the DataSet via an DataSetPrimaryKey.
     * @param 	id Long
     * @return 	DataSet
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public DataSet handle( FindDataSetQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getDataSetId() );
    }
    
    /**
     * Method to retrieve a collection of all DataSets
     *
     * @param	query	FindAllDataSetQuery 
     * @return 	List<DataSet> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<DataSet> handle( FindAllDataSetQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindDataSet,
 * but only if the id matches
 *
 * @param		entity	DataSet
 */
	protected void emitFindDataSet( DataSet entity ) {
		LOGGER.info("handling emitFindDataSet" );
		
	    queryUpdateEmitter.emit(FindDataSetQuery.class,
	                            query -> query.getFilter().getDataSetId().equals(entity.getDataSetId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllDataSet
	 * 
	 * @param		entity	DataSet
	 */
	protected void emitFindAllDataSet( DataSet entity ) {
		LOGGER.info("handling emitFindAllDataSet" );
		
	    queryUpdateEmitter.emit(FindAllDataSetQuery.class,
	                            query -> true,
	                            entity);
	}

